sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var metrics = {};

    var urlPatterns = [
        'api/now/table/cmdb_categories',
        'api/now/table/cmdb_ci',
        'api/now/table/cmdb_rel_type',
        'oauth_token.do'
    ];

    urlPatterns.forEach(function(pattern) {
        var logGr = new GlideAggregate('syslog_transaction');
        logGr.addQuery('type', 'rest');
        logGr.addQuery('url', 'CONTAINS', pattern);

        logGr.addAggregate('COUNT');
        logGr.addAggregate('AVG', 'response_time');
        logGr.addAggregate('AVG', 'sql_time');
        logGr.addAggregate('AVG', 'business_rule_time');

        var count = 0;
        var avgResponseTime = 0;
        var avgSqlTime = 0;
        var avgBusinessRuleTime = 0;

        logGr.query();

        if (logGr.next()) {
            count = logGr.getAggregate('COUNT');
            avgResponseTime = logGr.getAggregate('AVG', 'response_time');
            avgSqlTime = logGr.getAggregate('AVG', 'sql_time');
            avgBusinessRuleTime = logGr.getAggregate('AVG', 'business_rule_time');

            // Logging results
            gs.info("Pattern: " + pattern + ", Count: " + count);
        } else {
            // Logging a message if no data is found
            gs.info("No data found for pattern: " + pattern);
        }

        metrics[pattern] = {
            call_count: count,
            avg_response_time: avgResponseTime,
            avg_sql_time: avgSqlTime,
            avg_business_rule_time: avgBusinessRuleTime
        };
    });

    return metrics;

})(request, response);
